    static func string(_ key: String, locale: String?) -> String {
        let selected = locale == "pt-BR" || (locale == "auto" && Locale.preferredLanguages.first?.hasPrefix("pt") == true) ? "pt-BR" : "en-US"
        return translations[selected]?[key] ?? key
    }

    static func inferenceActiveLabel(id: String, fallback: String, locale: String?) -> String {
        let key: String
        switch id {
        case "auto": key = "inference.autoCoreML"
        case "ane": key = "inference.ane"
        case "gpu": key = "inference.gpu"
        case "cpu": key = "inference.cpu"
        default: return fallback
        }
        return string(key, locale: locale)
    }

    static func inferenceUnavailableLabel(id: String, locale: String?) -> String {
        string("inference.missingWithId", locale: locale).replacingOccurrences(of: "{0}", with: id)
    }

    static func cameraStatus(_ snapshot: CoreSnapshot, locale: String?) -> String {
        guard let camera = snapshot.camera else {
            return string("cameraStatus.unavailable", locale: locale)
        }
        let status = camera.display_status ?? camera.status ?? "unknown"
        return string("cameraStatus.\(status)", locale: locale)
    }

    static func cameraInlineStatus(status: String, locale: String?) -> String {
        "\(string("camera", locale: locale)): \(string("cameraStatus.\(status)", locale: locale))"
    }

    static func cameraInlineStatus(_ snapshot: CoreSnapshot, locale: String?) -> String {
        let status = snapshot.camera?.display_status ?? snapshot.camera?.status ?? "unavailable"
        return cameraInlineStatus(status: status, locale: locale)
    }
}
